  display: flex;
  flex-direction: column;
  gap: var(--sp-3);
}

.hatch-dream-composer__box {
  display: flex;
  flex-direction: column;
  gap: var(--sp-2);
}

.hatch-dream-composer__source {
  width: 100%;
}

.hatch-dream-composer__actions {
  display: flex;
  justify-content: flex-end;
}

@media (max-width: 40rem) {
  .hatch-dream-composer__actions > * {
    flex: 1 1 100%;
  }
}
